package com.bapreclicktomove;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(BAPreClickToMoveConfig.GROUP)
public interface BAPreClickToMoveConfig extends Config
{
	String GROUP = "bapreclicktomove";

	@ConfigSection(
		name = "Points interface boundary",
		description = "Outline of the part of the wave-complete interface that blocks clicks on the scene",
		position = 0
	)
	String pointsInterfaceBoundarySection = "pointsInterfaceBoundary";

	@ConfigSection(
		name = "Relative tile",
		description = "Outline of a tile at a fixed offset from the player, while in a wave lobby",
		position = 1
	)
	String relativeTileSection = "relativeTile";

	@ConfigItem(
		keyName = "showPointsInterfaceBoundary",
		name = "Show points interface boundary",
		description = "Outline the part of the wave-complete interface that blocks clicks on the scene behind it",
		section = pointsInterfaceBoundarySection,
		position = 0
	)
	default boolean showPointsInterfaceBoundary()
	{
		return false;
	}

	@ConfigItem(
		keyName = "scrollToZoom",
		name = "Scroll to zoom over interface",
		description = "Zoom the camera when scrolling over the part of the wave-complete interface that blocks the scene."
			+ " Needs the game's scroll-to-zoom setting on",
		section = pointsInterfaceBoundarySection,
		position = 1
	)
	default boolean scrollToZoom()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "outlineColor",
		name = "Outline color",
		description = "Color of the outline drawn along the points interface boundary",
		section = pointsInterfaceBoundarySection,
		position = 2
	)
	default Color outlineColor()
	{
		return Color.RED;
	}

	@Range(min = 1, max = 5)
	@ConfigItem(
		keyName = "outlineWidth",
		name = "Outline width",
		description = "Width of the outline, in pixels",
		section = pointsInterfaceBoundarySection,
		position = 3
	)
	default int outlineWidth()
	{
		return 2;
	}

	@Alpha
	@ConfigItem(
		keyName = "fillColor",
		name = "Fill color",
		description = "Color used to fill the area inside the points interface boundary (fully transparent by default)",
		section = pointsInterfaceBoundarySection,
		position = 4
	)
	default Color fillColor()
	{
		return new Color(255, 0, 0, 0);
	}

	@ConfigItem(
		keyName = "showRelativeTile",
		name = "Show relative tile",
		description = "While in a Barbarian Assault wave lobby, outline the tile at the offset below from the player",
		section = relativeTileSection,
		position = 0
	)
	default boolean showRelativeTile()
	{
		return false;
	}

	@Range(min = 0)
	@ConfigItem(
		keyName = "northSouthTiles",
		name = "Tiles north/south",
		description = "How many tiles north or south of the player the tile is",
		section = relativeTileSection,
		position = 1
	)
	default int northSouthTiles()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "northSouth",
		name = "North/South",
		description = "Whether the tile is north or south of the player",
		section = relativeTileSection,
		position = 2
	)
	default NorthSouth northSouth()
	{
		return NorthSouth.NORTH;
	}

	@Range(min = 0)
	@ConfigItem(
		keyName = "eastWestTiles",
		name = "Tiles east/west",
		description = "How many tiles east or west of the player the tile is",
		section = relativeTileSection,
		position = 3
	)
	default int eastWestTiles()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "eastWest",
		name = "East/West",
		description = "Whether the tile is east or west of the player",
		section = relativeTileSection,
		position = 4
	)
	default EastWest eastWest()
	{
		return EastWest.EAST;
	}

	@Alpha
	@ConfigItem(
		keyName = "tileColor",
		name = "Tile color",
		description = "Color of the relative tile's outline",
		section = relativeTileSection,
		position = 5
	)
	default Color tileColor()
	{
		return Color.CYAN;
	}

	@ConfigItem(
		keyName = "wave10Offset",
		name = "Different offset on wave 10",
		description = "In the wave 10 lobby, outline the tile at the wave 10 offset below instead."
			+ " The dispensers are placed differently relative to the spawns on wave 10",
		section = relativeTileSection,
		position = 6
	)
	default boolean wave10Offset()
	{
		return false;
	}

	@Range(min = 0)
	@ConfigItem(
		keyName = "wave10NorthSouthTiles",
		name = "Wave 10 tiles north/south",
		description = "How many tiles north or south of the player the tile is in the wave 10 lobby",
		section = relativeTileSection,
		position = 7
	)
	default int wave10NorthSouthTiles()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "wave10NorthSouth",
		name = "Wave 10 North/South",
		description = "Whether the tile is north or south of the player in the wave 10 lobby",
		section = relativeTileSection,
		position = 8
	)
	default NorthSouth wave10NorthSouth()
	{
		return NorthSouth.NORTH;
	}

	@Range(min = 0)
	@ConfigItem(
		keyName = "wave10EastWestTiles",
		name = "Wave 10 tiles east/west",
		description = "How many tiles east or west of the player the tile is in the wave 10 lobby",
		section = relativeTileSection,
		position = 9
	)
	default int wave10EastWestTiles()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "wave10EastWest",
		name = "Wave 10 East/West",
		description = "Whether the tile is east or west of the player in the wave 10 lobby",
		section = relativeTileSection,
		position = 10
	)
	default EastWest wave10EastWest()
	{
		return EastWest.EAST;
	}
}

package com.bapreclicktomove;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "BA Pre-Click to Move",
	description = "Barbarian Assault lobby helpers: outline the interface area that blocks scene clicks, zoom while scrolling over it, and outline a tile relative to the player",
	tags = {"barbarian", "assault", "ba", "minigame", "interface", "overlay", "zoom"}
)
public class BAPreClickToMovePlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PointsInterfaceBoundaryOverlay overlay;

	@Inject
	private RelativeTileOverlay relativeTileOverlay;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private InterfaceScrollToZoom interfaceScrollToZoom;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(relativeTileOverlay);
		mouseManager.registerMouseWheelListener(interfaceScrollToZoom);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(relativeTileOverlay);
		mouseManager.unregisterMouseWheelListener(interfaceScrollToZoom);
	}

	@Provides
	BAPreClickToMoveConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BAPreClickToMoveConfig.class);
	}
}

package com.bapreclicktomove;

import java.awt.Rectangle;
import java.awt.geom.Area;
import java.util.function.IntPredicate;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.WidgetNode;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetConfigNode;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.api.widgets.WidgetType;

/**
 * Computes the part of the viewport in which widgets stop the mouse from interacting with the scene.
 * <p>
 * This mirrors the client's widget mouse-input pass. The client walks the widget tree depth first, adding the
 * scene's menu entries when it reaches the viewport widget (content type 1337). A widget processed later that
 * contains the mouse then resets the menu to just "Cancel", which throws those scene entries away. Two things do
 * that reset:
 * <ul>
 *     <li>an if3 widget with {@code noClickThrough}, over its bounds clipped to its ancestors';</li>
 *     <li>a layer mounting an interface with modal mode {@link WidgetModalMode#MODAL_NOCLICKTHROUGH}, over the
 *     layer's clipped bounds.</li>
 * </ul>
 * Widgets with ops or listeners do not block: they add their own entries above the scene's but leave them in place.
 * <p>
 * The same resets also discard the queued mouse-wheel events, so the viewport's zoom does not happen over these
 * widgets either. Scrolling is additionally blocked by if3 widgets with {@code noScrollThrough}, which discard just
 * the mouse-wheel events.
 */
class BlockedAreaCalculator
{
	private static final int CONTENT_TYPE_VIEWPORT = 1337;
	private static final int CONTENT_TYPE_1338 = 1338;

	private final Client client;
	private final IntPredicate countsInterface;

	private Rectangle viewport;
	private Area clickBlocked;
	private Area scrollBlocked;

	@Value
	static class Result
	{
		/** Where the mouse cannot interact with the scene (hover, click, menu entries). */
		Area clickBlocked;
		/** Where mouse-wheel events do not reach the viewport; always contains {@link #clickBlocked}. */
		Area scrollBlocked;
	}

	/**
	 * @param countsInterface which interface (group) ids may contribute to the blocked area; blockers belonging to
	 *                        other interfaces still block the scene, but are left out of the result
	 */
	BlockedAreaCalculator(Client client, IntPredicate countsInterface)
	{
		this.client = client;
		this.countsInterface = countsInterface;
	}

	/**
	 * @return the blocked parts of the viewport, empty if nothing blocks it or there is no viewport
	 */
	Result compute()
	{
		viewport = null;
		clickBlocked = new Area();
		scrollBlocked = new Area();

		Widget[] roots = client.getWidgetRoots();
		if (roots != null)
		{
			visit(roots, new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight()));
		}

		if (viewport == null)
		{
			return new Result(new Area(), new Area());
		}
		Area view = new Area(viewport);
		clickBlocked.intersect(view);
		scrollBlocked.intersect(view);
		return new Result(clickBlocked, scrollBlocked);
	}

	private void visit(Widget[] widgets, Rectangle parentClip)
	{
		for (Widget w : widgets)
		{
			if (w != null)
			{
				visit(w, parentClip);
			}
		}
	}

	private void visit(Widget w, Rectangle parentClip)
	{
		if (!isProcessed(w))
		{
			return;
		}

		Rectangle clip = parentClip.intersection(w.getBounds());
		if (clip.isEmpty() && w.isIf3())
		{
			return;
		}

		if (w.getContentType() == CONTENT_TYPE_VIEWPORT)
		{
			viewport = clip;
		}
		else if (w.isIf3() && w.getNoClickThrough())
		{
			block(clip, w.getId());
		}
		else if (w.isIf3() && w.getNoScrollThrough())
		{
			if (counts(clip, w.getId()))
			{
				scrollBlocked.add(new Area(clip));
			}
		}

		Widget[] children = w.getStaticChildren();
		if (children != null)
		{
			visit(children, clip);
		}
		children = w.getDynamicChildren();
		if (children != null)
		{
			visit(children, clip);
		}

		WidgetNode node = client.getComponentTable().get(w.getId());
		if (node != null)
		{
			if (node.getModalMode() == WidgetModalMode.MODAL_NOCLICKTHROUGH)
			{
				block(clip, node.getId() << 16);
			}
			children = w.getNestedChildren();
			if (children != null)
			{
				visit(children, clip);
			}
		}
	}

	private void block(Rectangle clip, int componentId)
	{
		if (counts(clip, componentId))
		{
			Area area = new Area(clip);
			clickBlocked.add(area);
			scrollBlocked.add(area);
		}
	}

	private boolean counts(Rectangle clip, int componentId)
	{
		// Blockers processed before the viewport only discard entries and events that come before the scene's.
		return viewport != null && !clip.isEmpty() && countsInterface.test(componentId >>> 16);
	}

	/**
	 * The client's filter for which widgets take part in mouse input at all. A widget that fails it is skipped along
	 * with its whole subtree, so e.g. a plain if3 sprite with {@code noClickThrough} set does not block.
	 */
	private boolean isProcessed(Widget w)
	{
		if (!w.isIf3())
		{
			return true;
		}
		if (w.isSelfHidden())
		{
			return false;
		}

		int type = w.getType();
		if (type == WidgetType.LAYER || type == 11 || type == WidgetType.INPUT_FIELD
			|| w.hasListener() || w.getContentType() == CONTENT_TYPE_1338)
		{
			return true;
		}

		WidgetConfigNode config = client.getWidgetConfig(w);
		if (config != null)
		{
			return config.getClickMask() != 0 || config.getOpMask() != 0;
		}
		return w.getClickMask() != 0;
	}
}

